-- Fuller, first-person chips; my answers rewritten to answer each question directly.
update public.card_content set chips=array['A person who did the opposite of what I expected','A machine doing something I never built in','How much I''d changed without noticing'], mine='How often the right fix turned out to be a conversation, not code.' where question_id='surprised';
update public.card_content set chips=array['Getting everyone to agree on what we''re building','Too much to do and no clear order','Working out which problem actually matters'], mine='Explaining, in one sentence, what a forward-deployed engineer actually does.' where question_id='hardest-problem';
update public.card_content set chips=array['Chasing a bug I refused to walk away from','A conversation that ran three hours','A book I opened for five minutes'], mine='Wiring up the twentieth tool and watching the agent finally use it right.' where question_id='lost-time';
update public.card_content set chips=array['Deleting one app from my phone','Eating lunch away from my desk','A walk with no podcast'], mine='Writing the day''s three things on paper before opening the laptop.' where question_id='small-improvement';
update public.card_content set chips=array['Something useless and beautiful','The thing nobody would fund','Finish the project I abandoned'], mine='A tool that reads a contract and tells you only what changed.' where question_id='free-week';
update public.card_content set chips=array['Meetings about the meeting','Whatever tool launched this week','Moving fast with nothing to show'], mine='Demos. Anyone can demo; getting fifty real people to use it is the hard part.' where question_id='overrated';
update public.card_content set chips=array['An instrument, played properly','A language, enough to joke in','Something with my hands, like pottery'], mine='Dancing. I''d happily be bad at it for years.' where question_id='skill-if-free';
update public.card_content set chips=array['Parallel parking on the first try','Remembering a name after one meeting','Packing for a week in one bag'], mine='Finding the one line in a four-hundred-line log that actually matters.' where question_id='unreasonably-good';
update public.card_content set chips=array['A problem at work I can''t put down','A side project, usually at 11pm','Nothing, honestly. I switch off fine'], mine='How to let an agent act without ever letting it act alone.' where question_id='cant-stop';
update public.card_content set chips=array['Space, and how big it really is','How cities decide where things go','The chemistry of fermentation'], mine='How cities decide where to put things.' where question_id='curious-outside-work';
update public.card_content set chips=array['Hiring someone you''ll work with for years','Writing something you actually mean','Cooking a meal for people you like'], mine='Deciding what the first version is. After that, everything can be fast.' where question_id='worth-slowly';
update public.card_content set chips=array['A proper meal, from scratch','Something fixed with tape and optimism','Nothing lately, and I miss it'], mine='Dinner, badly.' where question_id='made-by-hand';
update public.card_content set chips=array['That it''s mostly typing code','That I work alone all day','That it''s all logic and no judgment'], mine='That it''s building software. Most of it is working out what''s actually being asked.' where question_id='job-misunderstood';
update public.card_content set chips=array['A colleague who never meant to teach me','A stranger who said one useful sentence','Someone I argued with and lost to'], mine='A lawyer who kept saying "that''s not how it works" until I understood why.' where question_id='taught-me-most';
update public.card_content set chips=array['A tool I built for exactly one person','A script only I still run','Several, honestly. Don''t ask'], mine='A small tool I built for one person, who then changed jobs.' where question_id='nobody-uses';
update public.card_content set chips=array['Ask the question sooner','Nobody is watching as closely as you think','Small habits beat raw talent'], mine='You can just go and talk to the people who use the thing.' where question_id='five-years-ago';
update public.card_content set chips=array['Every status update, forever','Expense reports and receipts','Scheduling across time zones'], mine='Chasing signatures.' where question_id='automate-forever';
update public.card_content set chips=array['I used to think more process meant better teams','I used to think busy meant productive','I used to think the plan comes before the work'], mine='I used to think good specs came first. They come from sitting with the work.' where question_id='changed-mind';
update public.card_content set chips=array['Saying no without a long apology','Shipping the rough version early','Listening before I answer'], mine='Asking the dumb question early instead of the smart one late.' where question_id='better-than-last-year';
update public.card_content set chips=array['Making hard things feel easy for others','One thing I built that lasted','Being the calm one when things broke'], mine='That what I built was still standing after I left.' where question_id='remembered-for';
update public.card_content set chips=array['Making something everyone hates less awful','Teaching people something that sticks','One small thing, understood deeply'], mine='Making legal work feel less like paperwork and more like progress.' where question_id='decade-problem';
update public.card_content set chips=array['Start the whole thing over, simpler','Say the obvious thing out loud','Work less and think more'], mine='Ship the rough version on day one and let people argue with it.' where question_id='if-nobody-judged';
update public.card_content set chips=array['"Play it safe." I didn''t','"Pick a lane." I didn''t','"Wait your turn." I didn''t'], mine='"Pick one stack and stay in it."' where question_id='ignored-advice';
update public.card_content set chips=array['What not to do, in detail','How to leave well','How I behave under pressure'], mine='A process nobody questions is usually the real bug.' where question_id='bad-job';
update public.card_content set chips=array['A change I''ve been putting off','Something steady and good','I honestly don''t know yet'], mine='Landing somewhere I get to sit with customers again.' where question_id='this-year';
